style:
/* 素笺 —— 米白纸面 + 四角柔色块 + 右侧证件照 + 绿色圆徽标题 */

/* ── 纸面：米白底，裁掉溢出的装饰，打印也保留底色 ── */
.tw-cosolar--sujian.resume-paper {
  background: #f7f4ec;
  color: #2b3630;
  overflow: hidden;
  print-color-adjust: exact;
}

/* ── 四角柔色块：左上青绿、右下米金；另外两块挂在正文流上，贴纸角 ── */
.tw-cosolar--sujian.resume-paper::before {
  content: "";
  position: absolute;
  top: -16mm;
  left: -14mm;
  width: 60mm;
  height: 48mm;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(120, 176, 148, 0.32), rgba(120, 176, 148, 0));
  pointer-events: none;
}

.tw-cosolar--sujian.resume-paper::after {
  content: "";
  position: absolute;
  right: -14mm;
  bottom: -18mm;
  width: 66mm;
  height: 52mm;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(198, 176, 137, 0.28), rgba(198, 176, 137, 0));
  pointer-events: none;
}

.tw-cosolar--sujian.resume-paper .paper-flow {
  position: relative;
}

.tw-cosolar--sujian.resume-paper .paper-flow::before {
  content: "";
  position: absolute;
  top: -13mm;
  right: -13mm;
  width: 42mm;
  height: 34mm;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(214, 196, 162, 0.24), rgba(214, 196, 162, 0));
  pointer-events: none;
}

.tw-cosolar--sujian.resume-paper .paper-flow::after {
  content: "";
  position: absolute;
  bottom: -14mm;
  left: -16mm;
  width: 48mm;
  height: 38mm;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(170, 204, 186, 0.20), rgba(170, 204, 186, 0));
  pointer-events: none;
}

/* ── 页眉：姓名与求职意向同一行，照片贴右，基本信息两列铺满 ── */
.tw-cosolar--sujian.resume-paper .paper-header {
  margin-bottom: 2.2mm;
  padding-bottom: 4.2mm;
  border-bottom: 1px solid #dfe8e0;
}

.tw-cosolar--sujian.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-cosolar--sujian.resume-paper .paper-header__main {
  flex: 1 1 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 7mm;
  row-gap: 1mm;
  min-width: 0;
}

.tw-cosolar--sujian.resume-paper .paper-name-row {
  flex: 0 0 auto;
}

.tw-cosolar--sujian.resume-paper .paper-name {
  color: #1f2b26;
  font-size: calc(var(--paper-base-size) * 2.35);
  font-weight: 700;
  letter-spacing: 0.02em;
}

.tw-cosolar--sujian.resume-paper .paper-identity {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #7c8a82;
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-cosolar--sujian.resume-paper .paper-role {
  flex: 0 0 auto;
  margin-top: 0;
  color: #3d4a44;
  font-size: calc(var(--paper-base-size) * 1.04);
  font-weight: 600;
}

.tw-cosolar--sujian.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7c8a82;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

/* 证件照：圆角白边、轻微投影，读起来像贴在纸上的一张照片 */
.tw-cosolar--sujian.resume-paper .paper-photo {
  order: 2;
  width: 26mm;
  height: 34.5mm;
  border: 1.2mm solid #ffffff;
  border-radius: 2.4mm;
  object-fit: cover;
  box-shadow: 0 2mm 7mm -3mm rgba(47, 66, 57, 0.38);
  print-color-adjust: exact;
}

.tw-cosolar--sujian.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  width: 24mm;
  height: 24mm;
  border: 1mm solid #ffffff;
  border-radius: 50%;
  background: #e6f0ea;
  color: #649b80;
  font-size: calc(var(--paper-base-size) * 1.9);
  font-weight: 600;
}

/* 基本信息：两列标签网格，读作「性别 女」「居住地 上海」 */
.tw-cosolar--sujian.resume-paper .paper-contacts--labeled {
  flex: 1 0 100%;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.1mm 10mm;
  margin-top: 5.2mm;
  padding: 0;
  border: none;
  color: #33403a;
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-cosolar--sujian.resume-paper .paper-contact {
  display: flex;
  gap: 1.8mm;
  min-width: 0;
}

.tw-cosolar--sujian.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--sujian.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #8d9a92;
}

/* ── 模块标题：绿色实心圆徽 + 深色标题 + 通栏细线 ── */
.tw-cosolar--sujian.resume-paper .paper-style-icon .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin: 0 0 3mm;
  color: #232e28;
  font-size: calc(var(--paper-base-size) * 1.12);
  font-weight: 700;
  letter-spacing: 0.02em;
}

.tw-cosolar--sujian.resume-paper .paper-style-icon .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 5.4mm;
  height: 5.4mm;
  border: none;
  border-radius: 50%;
  background: var(--paper-accent);
  color: #ffffff;
  print-color-adjust: exact;
}

.tw-cosolar--sujian.resume-paper .paper-style-icon .paper-section__icon svg {
  width: 56%;
  height: 56%;
}

.tw-cosolar--sujian.resume-paper .paper-style-icon .paper-section__title::after {
  content: "";
  flex: 1;
  align-self: center;
  border-top: 1px solid #dfe8e0;
}

/* ── 条目：日期 / 单位 / 职位三段铺开，右侧信息用主题绿 ── */
.tw-cosolar--sujian.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 5mm;
  row-gap: 1mm;
}

.tw-cosolar--sujian.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-cosolar--sujian.resume-paper .paper-item > .paper-item-head {
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: 6mm;
}

.tw-cosolar--sujian.resume-paper .paper-item-period {
  order: -1;
  color: #43514a;
  font-size: calc(var(--paper-base-size) * 0.96);
  font-weight: 600;
}

.tw-cosolar--sujian.resume-paper .paper-item-title {
  color: #1f2b26;
  font-weight: 700;
}

.tw-cosolar--sujian.resume-paper .paper-item > .paper-item-sub {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #5c8f76;
  font-weight: 600;
}

.tw-cosolar--sujian.resume-paper .paper-item-sub span + span::before {
  content: " · ";
  margin-right: 0;
  color: #b7c4bc;
}

/* 求职意向：跟其他模块同一套读法——岗位做主语、城市跟在后面，薪资与状态照旧靠右走主题绿。
   这里只调顺序与字号，条目骨架全部交给上面的通用规则，免得这一段又长成一处孤例。 */
.tw-cosolar--sujian.resume-paper .is-job_intention .paper-item-period {
  order: 0;
  color: #5c8f76;
  font-size: calc(var(--paper-base-size) * 0.96);
}

.tw-cosolar--sujian.resume-paper .is-job_intention .paper-item-title {
  font-size: calc(var(--paper-base-size) * 1.08);
}

/* ── 正文细节：课程标签、GPA、列表符号都跟主题绿 ── */
.tw-cosolar--sujian.resume-paper .paper-note {
  color: #5f6d65;
}

.tw-cosolar--sujian.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: #5c8f76;
  font-weight: 600;
}

.tw-cosolar--sujian.resume-paper .paper-item-tag {
  color: #5c8f76;
}

.tw-cosolar--sujian.resume-paper .paper-meta-line {
  color: #7c8a82;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--sujian.resume-paper .paper-rich {
  color: #4a584f;
}

.tw-cosolar--sujian.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

/* 技能：只留「名称 + 熟练度」，点阵在小版式里太吵 */
.tw-cosolar--sujian.resume-paper .paper-skill {
  border-bottom: 1px solid #e6ede7;
}

.tw-cosolar--sujian.resume-paper .paper-skill__name {
  color: #33403a;
  font-weight: 600;
}

.tw-cosolar--sujian.resume-paper .paper-skill__dots {
  display: none;
}

.tw-cosolar--sujian.resume-paper .paper-skill__level {
  display: inline;
  color: #6b7a72;
  font-size: calc(var(--paper-base-size) * 0.86);
}

/* 页脚保持克制：一条发丝线 + 浅灰字 */
.tw-cosolar--sujian.resume-paper .paper-footer {
  margin-top: 8mm;
  padding-top: 2.6mm;
  border-top: 1px solid #dfe8e0;
  color: #9aa79f;
}

@media print {
  .tw-cosolar--sujian.resume-paper {
    background: #f7f4ec;
    print-color-adjust: exact;
  }
}
